<template><section class="card card-body"><header class="implementation-heading"><h2>Processos salvos</h2><button class="btn" @click="load">Atualizar</button></header><p role="status">{{message}}</p><p v-if="!rows.length&&!loading">Nenhum processo salvo nesta conta.</p><div class="table-wrap" v-if="rows.length"><table><thead><tr><th>Processo</th><th>Atualizado</th><th>Revisão</th><th>Ações</th></tr></thead><tbody><tr v-for="r in rows" :key="r.id"><td>{{r.name||r.purpose||r.id}}</td><td>{{new Date(r.updated_at).toLocaleString('pt-BR')}}</td><td>{{r.version}}</td><td><button class="btn sm" @click="open(r)">Continuar</button> <button class="btn sm" @click="history(r)">Histórico</button> <button class="btn danger sm" @click="cancel(r)">Cancelar</button></td></tr></tbody></table></div><section v-if="versions.length"><h3>Revisões gravadas</h3><ol><li v-for="v in versions" :key="v.version">Revisão {{v.version}} · {{v.created_at}} <button class="btn sm" @click="download(v)">Baixar JSON</button></li></ol><button v-if="historyMore" class="btn" :disabled="historyLoading" @click="older">{{historyLoading?'Consultando…':'Carregar revisões anteriores'}}</button></section></section></template>
<script setup lang="ts">
import {ref,onMounted,onBeforeUnmount,onActivated} from 'vue';import {useRouter} from 'vue-router';import {runtime} from './runtime';
const rows=ref<any[]>([]),versions=ref<any[]>([]),loading=ref(false),historyMore=ref(false),historyLoading=ref(false),message=ref(''),router=useRouter();let closed=false,historyId='',historyCursor='',historyGeneration=0;
async function load(){loading.value=true;try{const rt=runtime();const data=await Promise.all(['import','laudo'].map(kind=>rt.json('/documents?account_id='+encodeURIComponent(rt.accountId)+'&kind='+kind)));if(!closed)rows.value=data.flatMap((r:any)=>r.data).filter((r:any)=>r.status!=='cancelled');}catch(e){if(!closed)message.value=(e as Error).message;}finally{if(!closed)loading.value=false;}}
function open(r:any){void router.push({path:r.mode==='laudo'?'/laudos':'/planilhas/'+(r.mode||'pre'),query:{process:r.id}});}
async function history(r:any){historyGeneration++;historyLoading.value=false;historyId=r.id;historyCursor='';historyMore.value=false;versions.value=[];await older();}
async function older(){if(historyLoading.value)return;const generation=++historyGeneration,id=historyId;historyLoading.value=true;try{const rt=runtime(),result=await rt.json('/documents/'+id+'/versions?account_id='+encodeURIComponent(rt.accountId)+(historyCursor?'&before='+encodeURIComponent(historyCursor):''));if(!closed&&historyId===id&&historyGeneration===generation){versions.value.push(...result.data);historyMore.value=result.more===true;historyCursor=result.next_cursor||'';}}catch(e){if(!closed)message.value=(e as Error).message;}finally{if(!closed&&historyGeneration===generation)historyLoading.value=false;}}
async function cancel(r:any){if(!confirm('Cancelar este processo salvo?'))return;try{await runtime().json('/documents/'+r.id,{account_id:runtime().accountId,expected_version:r.version},'DELETE');await load();}catch(e){if(!closed)message.value=(e as Error).message;}}
async function download(v:any){try{const rt=runtime(),result=await rt.json('/documents/'+historyId+'/versions/'+v.id+'?account_id='+encodeURIComponent(rt.accountId));if(closed)return;const url=rt.URL.createObjectURL(new Blob([JSON.stringify(result.data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='revisao-'+v.version+'.json';a.click();rt.URL.revokeObjectURL(url);}catch(e){if(!closed)message.value=(e as Error).message;}}
onMounted(load);onActivated(()=>{if(!loading.value)void load();});onBeforeUnmount(()=>{closed=true;rows.value=[];versions.value=[];});
</script>
